  impact_hammer: { id: "impact_hammer", name: "震荡重锤", type: "equipment", effect: "impact", slot: "weapon", rangeBonus: 2, icon: "震", description: "攻击距离+2；每回合首次以突击造成伤害后，目标弃1张手牌。", color: "orange" },
