  adaptive_armor: { id: "adaptive_armor", name: "自适应外衣", type: "equipment", effect: "basicAsGuard", slot: "armor", icon: "适", description: "每轮一次，可将一张非防御、非应变基础牌当防御。", color: "blue" },
